<?php /** Site header — mirrors SiteShell in src/components/site-shell.tsx. */ $rjy_logo = has_custom_logo() ? wp_get_attachment_image_url( get_theme_mod( 'custom_logo' ), 'full' ) : rjy_group_asset( 'rjy-logo-white.webp' ); $rjy_groups = rjy_group_nav_groups(); ?><!doctype html> <html <?php language_attributes(); ?>> <head><meta charset="<?php bloginfo( 'charset' ); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="anonymous"><?php wp_head(); ?></head> <body <?php body_class(); ?>><?php wp_body_open(); ?> <a class="skip-link screen-reader-text" href="#primary"><?php esc_html_e( 'Skip to content', 'rjy-group' ); ?></a> <div class="min-h-screen bg-background text-foreground"> <header class="site-header"><div class="main-nav"><div class="site-container flex h-full items-center justify-between gap-6"><a href="<?php echo esc_url( home_url( '/' ) ); ?>" aria-label="<?php esc_attr_e( 'RJY Group home', 'rjy-group' ); ?>"><img src="<?php echo esc_url( $rjy_logo ); ?>" alt="<?php echo esc_attr( get_bloginfo( 'name' ) ); ?>" class="brand-logo" width="281" height="79"></a> <nav class="desktop-nav hidden items-center md:flex" aria-label="<?php esc_attr_e( 'Main navigation', 'rjy-group' ); ?>"><a class="nav-link" href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'Home', 'rjy-group' ); ?></a><?php foreach ( $rjy_groups as $group ) : ?><div class="group relative"><button class="nav-trigger" type="button" aria-haspopup="true"><?php echo esc_html( $group['label'] ); ?><?php echo rjy_group_icon( 'chevron-down' ); ?></button><div class="nav-menu"><?php foreach ( $group['items'] as $index => $item ) : ?><a href="<?php echo esc_url( $item['url'] ); ?>"><span><small><?php echo esc_html( sprintf( '%02d', $index + 1 ) ); ?></small><?php echo esc_html( $item['label'] ); ?></span><?php echo rjy_group_icon( 'arrow-right' ); ?></a><?php endforeach; ?></div></div><?php endforeach; ?><?php echo rjy_group_button_link( '/contact', __( 'Contact Us', 'rjy-group' ), 'default', 'lg', 'desktop-contact' ); ?></nav> <button class="<?php echo esc_attr( rjy_group_button_class( 'ghost', 'icon', 'menu-toggle md:hidden' ) ); ?>" type="button" aria-controls="mobile-nav" aria-expanded="false" aria-label="<?php esc_attr_e( 'Open menu', 'rjy-group' ); ?>" data-open-label="<?php esc_attr_e( 'Open menu', 'rjy-group' ); ?>" data-close-label="<?php esc_attr_e( 'Close menu', 'rjy-group' ); ?>"><span class="hamburger" aria-hidden="true"><i></i><i></i><i></i></span><?php echo str_replace( '<svg ', '<svg hidden ', rjy_group_icon( 'x' ) ); ?></button> </div></div> <nav class="mobile-nav" id="mobile-nav" aria-label="<?php esc_attr_e( 'Mobile navigation', 'rjy-group' ); ?>" hidden><div class="mobile-nav-inner"><a class="mobile-nav-primary" href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'Home', 'rjy-group' ); ?> <?php echo rjy_group_icon( 'arrow-right' ); ?></a><?php foreach ( $rjy_groups as $group ) : ?><details><summary><?php echo esc_html( $group['label'] ); ?><?php echo rjy_group_icon( 'chevron-down' ); ?></summary><div><?php foreach ( $group['items'] as $item ) : ?><a href="<?php echo esc_url( $item['url'] ); ?>"><?php echo esc_html( $item['label'] ); ?><?php echo rjy_group_icon( 'arrow-right' ); ?></a><?php endforeach; ?></div></details><?php endforeach; ?><a class="mobile-contact-link" href="<?php echo esc_url( rjy_group_url( '/contact' ) ); ?>"><?php esc_html_e( 'Contact Us', 'rjy-group' ); ?> <?php echo rjy_group_icon( 'arrow-right' ); ?></a><div class="mobile-nav-contact"><p><?php esc_html_e( 'Speak with our team', 'rjy-group' ); ?></p><a href="<?php echo esc_url( rjy_group_phone_href( rjy_group_contact_mod( 'rjy_phone' ) ) ); ?>"><?php echo rjy_group_icon( 'phone' ); ?><?php echo esc_html( rjy_group_contact_mod( 'rjy_phone' ) ); ?></a><a href="<?php echo esc_url( rjy_group_phone_href( rjy_group_contact_mod( 'rjy_toll_free' ) ) ); ?>"><?php echo rjy_group_icon( 'phone' ); ?><?php echo esc_html( rjy_group_contact_mod( 'rjy_toll_free' ) ); ?></a><a href="mailto:<?php echo esc_attr( antispambot( rjy_group_contact_mod( 'rjy_email' ) ) ); ?>"><?php echo rjy_group_icon( 'mail' ); ?><?php echo esc_html( antispambot( rjy_group_contact_mod( 'rjy_email' ) ) ); ?></a></div></div></nav> </header> <main id="primary">
